SELECT orders.channel, orders.status, COUNT(CASE WHEN shipments.status = 'LOST' THEN 1 END) AS lost_count, ROUND((100 * SUM(CASE WHEN shipments.carrier = 'UPS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_ups FROM shipments INNER JOIN orders ON orders.id = shipments.order_id GROUP BY orders.channel, orders.status HAVING ROUND((100 * SUM(CASE WHEN shipments.carrier = 'UPS' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 43 ORDER BY status ASC
